def execute(
    self,
    backend: Backend,
    fmt: Any,
    file_path: str,
    file_content: str,
    class_name: str = "ModuleScript",
    **_: Any,
) -> Result:
    if backend.exists(file_path):
        return Result(
            status="error",
            message=f"Файл уже существует: {file_path}. Используйте overwrite_file.",
            action="create_file",
            error_code="already_exists",
        )
    err = _check_content_syntax(file_path, file_content)
    if err is not None:
        return Result(
            status="error",
            message=f"Не создаю {file_path}: {err}",
            action="create_file",
            error_code="content_syntax_error",
        )
    create_fn = getattr(backend, "create", None)
    try:
        if callable(create_fn):
            create_fn(file_path, file_content, class_name=class_name)
        else:
            backend.write(file_path, file_content)
    except FileExistsError:
        return Result(
            status="error",
            message=f"Файл уже существует: {file_path}. Используйте overwrite_file.",
            action="create_file",
            error_code="already_exists",
        )
    except Exception as e:
        return Result(
            status="error",
            message=f"Не удалось создать {file_path}: {e}",
            action="create_file",
            error_code="create_failed",
        )
    st = backend.stat(file_path)
    return Result(
        status="ok",
        message=f"Файл создан: {file_path} ({st.lines} стр., {st.size_bytes} Б)",
        action="create_file",
    )

def _normalize_parts(part) -> list[str]:
    """Accept `head`, `head,annotation`, `[\"head\", \"annotation\"]`.

    A bare string may hold a comma-separated list — same format the CLI
    uses — so both `part="head,annotation"` and `part=["head", "annotation"]`
    work identically.

    `own_body` is a section-only variant of `body`: the section's own
    text up to (not including) its first subsection. For non-section
    units it behaves like `body`.
    """
    if part is None:
        return ["all"]
    if isinstance(part, str):
        parts = [p.strip() for p in part.split(",") if p.strip()]
    elif isinstance(part, list):
        parts = [str(p).strip() for p in part if str(p).strip()]
    else:
        raise ValueError(f"bad_part: {part!r}")
    if not parts:
        raise ValueError(f"bad_part: {part!r}")
    valid = {"all", "head", "annotation", "body", "own_body"}
    for p in parts:
        if p not in valid:
            raise ValueError(f"bad_part: {p!r}")
    if "all" in parts:
        return ["all"]
    return [p for p in ("head", "annotation", "body", "own_body")
            if p in parts]

def _render_unit(source: str, unit: Unit, parts: list[str], blocks: list[int]) -> str:
    if blocks:
        return _render_blocks(source, unit, parts, blocks)
    if not parts or parts == ["all"]:
        return _slice_lines(source, unit.line_start, unit.line_end)
    chunks: list[str] = []
    for p in ("head", "annotation", "body", "own_body"):
        if p not in parts:
            continue
        if p == "own_body":
            text = _slice(source, _own_body_part(unit))
        else:
            text = _slice(source, getattr(unit, p))
        if text:
            chunks.append(text)
    return "\n".join(chunks)


def _own_body_part(unit: Unit):
    """Body range excluding subsections (blocks that carry their own unit).

    Section-only in practice: the section's own prose before the first
    `###`-child. For a unit without subsection-blocks it equals `body`.
    """
    from .model import Part as _P
    if not unit.body.is_present():
        return _P()
    first_child = None
    for b in unit.blocks:
        if b.unit is not None:
            first_child = b.start
            break
    if first_child is None:
        return unit.body
    end = first_child - 1
    while end >= unit.body.start and not _line_nonblank(unit, end):
        end -= 1
    if end < unit.body.start:
        return _P()
    return _P(unit.body.start, end)

